import {dateValidator} from './date-validator';

// all tests were entirely generated by claude
describe('dateValidator', () => {
    it('accepts a valid date', () => {
        expect(dateValidator('2016-04-24')).toBeNull();
    });

    it('accepts a leap day in a leap year', () => {
        expect(dateValidator('2020-02-29')).toBeNull();
    });

    it('accepts the last day of the year', () => {
        expect(dateValidator('2020-12-31')).toBeNull();
    });

    it('accepts the first day of the year', () => {
        expect(dateValidator('2020-01-01')).toBeNull();
    });

    it('rejects a leap day in a non-leap year', () => {
        expect(dateValidator('2019-02-29')).toEqual(expect.any(String));
    });

    it('rejects a leap day in a century non-leap year', () => {
        expect(dateValidator('1900-02-29')).toEqual(expect.any(String));
    });

    it('rejects day 31 in a 30-day month', () => {
        expect(dateValidator('2020-04-31')).toEqual(expect.any(String));
    });

    it('rejects February 31', () => {
        expect(dateValidator('2020-02-31')).toEqual(expect.any(String));
    });

    it('rejects month 13', () => {
        expect(dateValidator('2020-13-01')).toEqual(expect.any(String));
    });

    it('rejects month 00', () => {
        expect(dateValidator('2020-00-10')).toEqual(expect.any(String));
    });

    it('rejects day 00', () => {
        expect(dateValidator('2020-01-00')).toEqual(expect.any(String));
    });

    it('rejects month and day without leading zero', () => {
        expect(dateValidator('2020-2-3')).toEqual(expect.any(String));
    });

    it('rejects two-digit year', () => {
        expect(dateValidator('20-02-03')).toEqual(expect.any(String));
    });

    it('rejects dots as separator', () => {
        expect(dateValidator('2020.02.03')).toEqual(expect.any(String));
    });

    it('rejects German format DD.MM.YYYY', () => {
        expect(dateValidator('24.04.2016')).toEqual(expect.any(String));
    });

    it('rejects letters', () => {
        expect(dateValidator('abcd-ef-gh')).toEqual(expect.any(String));
    });

    it('rejects empty string', () => {
        expect(dateValidator('')).toEqual(expect.any(String));
    });

    it('rejects leading space', () => {
        expect(dateValidator(' 2016-04-24')).toEqual(expect.any(String));
    });

    it('rejects trailing space', () => {
        expect(dateValidator('2016-04-24 ')).toEqual(expect.any(String));
    });

    it('rejects date with time part', () => {
        expect(dateValidator('2016-04-24T10:00')).toEqual(expect.any(String));
    });
});